def clamp(value, lo, hi):
    if value < lo:
        return lo
    if value > hi:
        return hi
    return value


def sign(value):
    if value > 0:
        return 1
    elif value < 0:
        return -1
    else:
        return 0


def is_even(value):
    return value % 2 == 0


def first_or_none(values):
    if not values:
        return None
    return values[0]


def last_or_none(values):
    if not values:
        return None
    return values[-1]


def count_nonempty(values):
    count = 0
    for v in values:
        if len(v) > 0:
            count += 1
    return count


def reverse_text(text):
    return text[::-1]
